import unittest
from component import handle

class GainTests(unittest.TestCase):
    def test_measured(self):
        self.assertEqual(handle({"before": 3, "after": 4}), {"gain": 1})

    def test_unmeasured(self):
        self.assertEqual(handle({"before": None, "after": None}), {"gain": "not run"})
